import math
import unittest

from solution import continuous_turns


class ContinuousTurnsTests(unittest.TestCase):
    def test_empty_and_single_sample(self):
        samples = []
        result = continuous_turns(samples)
        self.assertEqual(result, [])
        self.assertIsNot(result, samples)
        self.assertEqual(continuous_turns([725]), [725])

    def test_unwraps_in_both_directions_relative_to_previous_result(self):
        samples = [350.0, 10.0, 20.0, 350.0, 340.0]
        self.assertEqual(
            continuous_turns(samples),
            [350.0, 370.0, 380.0, 350.0, 340.0],
        )

    def test_adjusts_by_multiple_whole_turns(self):
        self.assertEqual(
            continuous_turns([10.0, 1090.0, -1070.0]),
            [10.0, 10.0, 10.0],
        )
        self.assertEqual(continuous_turns([0.0, 25.0], full_turn=10.0), [0.0, 5.0])

    def test_closed_half_turn_boundaries_remain_unchanged(self):
        self.assertEqual(continuous_turns([0.0, 180.0]), [0.0, 180.0])
        self.assertEqual(continuous_turns([0.0, -180.0]), [0.0, -180.0])
        self.assertEqual(
            continuous_turns([5.0, 10.0, 5.0], full_turn=10.0),
            [5.0, 10.0, 5.0],
        )

    def test_output_is_new_and_input_is_unchanged(self):
        samples = [350.0, 10.0]
        before = list(samples)
        result = continuous_turns(samples)
        self.assertEqual(samples, before)
        self.assertIsNot(result, samples)
        result.append(999.0)
        self.assertEqual(samples, before)

    def test_invalid_outer_sample_and_turn_types(self):
        for bad in ((), None, "0,1"):
            with self.subTest(samples=bad), self.assertRaises(TypeError):
                continuous_turns(bad)
        for bad in (True, "360", None, complex(360, 0)):
            with self.subTest(full_turn=bad), self.assertRaises(TypeError):
                continuous_turns([], bad)
        for bad in (True, "1", None, complex(1, 0)):
            with self.subTest(sample=bad), self.assertRaises(TypeError):
                continuous_turns([bad])

    def test_nonfinite_and_nonpositive_values(self):
        for bad in (float("nan"), float("inf"), float("-inf")):
            with self.subTest(sample=bad), self.assertRaises(ValueError):
                continuous_turns([bad])
        for bad in (0, -1, float("nan"), float("inf"), float("-inf")):
            with self.subTest(full_turn=bad), self.assertRaises(ValueError):
                continuous_turns([], bad)


if __name__ == "__main__":
    unittest.main()

